CREATE OR REPLACE FUNCTION public.validate_customer_order_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_order_user_id uuid;
  v_session_order_id uuid;
  v_parent public.customer_order_messages%rowtype;
begin
  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id
      or new.user_id is distinct from old.user_id
      or new.order_id is distinct from old.order_id
      or new.packing_session_id is distinct from old.packing_session_id
      or new.sender_type is distinct from old.sender_type
      or new.message_kind is distinct from old.message_kind
      or new.reply_to_message_id is distinct from old.reply_to_message_id
      or new.sender_name is distinct from old.sender_name
      or new.subject is distinct from old.subject
      or new.body is distinct from old.body
      or new.created_at is distinct from old.created_at
      or (
        new.sender_admin_user_id is distinct from old.sender_admin_user_id
        and not (
          old.sender_admin_user_id is not null
          and new.sender_admin_user_id is null
        )
      )
      or (
        new.sender_customer_user_id is distinct from old.sender_customer_user_id
        and not (
          old.sender_customer_user_id is not null
          and new.sender_customer_user_id is null
        )
      )
    then
      raise exception 'Order message sender, conversation, and content are immutable.';
    end if;
  end if;

  if new.order_id is not null then
    select orders.user_id
    into v_order_user_id
    from public.customer_orders as orders
    where orders.id = new.order_id;

    if not found or v_order_user_id is distinct from new.user_id then
      raise exception 'The message recipient does not own the selected order.';
    end if;
  end if;

  if new.packing_session_id is not null then
    select sessions.order_id
    into v_session_order_id
    from public.order_packing_sessions as sessions
    where sessions.id = new.packing_session_id;

    if not found
      or new.order_id is null
      or v_session_order_id is distinct from new.order_id
    then
      raise exception 'The message packing session does not match its order.';
    end if;
  end if;

  if new.reply_to_message_id is not null then
    select messages.*
    into v_parent
    from public.customer_order_messages as messages
    where messages.id = new.reply_to_message_id;

    if not found
      or v_parent.user_id is distinct from new.user_id
      or v_parent.order_id is distinct from new.order_id
      or v_parent.sender_type <> 'admin'
      or v_parent.message_kind <> 'packing_problem'
      or v_parent.reply_to_message_id is not null
    then
      raise exception 'Customer replies must target the matching order problem message.';
    end if;
  end if;

  if new.sender_type = 'admin' then
    if tg_op = 'INSERT' and new.sender_admin_user_id is null then
      raise exception 'An admin sender is required for this order message.';
    end if;

    if new.sender_customer_user_id is not null
      or new.message_kind not in ('order_update', 'packing_problem')
      or new.reply_to_message_id is not null
    then
      raise exception 'The admin order message sender is not valid.';
    end if;
  elsif new.sender_type = 'customer' then
    if new.sender_admin_user_id is not null
      or new.sender_customer_user_id is distinct from new.user_id
      or new.message_kind <> 'customer_reply'
      or new.reply_to_message_id is null
      or new.packing_session_id is not null
    then
      raise exception 'The customer order reply sender is not valid.';
    end if;

    new.read_at := coalesce(new.read_at, clock_timestamp());
  else
    raise exception 'The order message sender type is not valid.';
  end if;

  if new.message_kind = 'packing_problem'
    and new.packing_session_id is null
  then
    raise exception 'A packing problem must identify its packing session.';
  end if;

  new.sender_name := btrim(new.sender_name);
  new.subject := btrim(new.subject);
  new.body := btrim(new.body);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_order_packing_scan()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare
  v_session public.order_packing_sessions%rowtype;
  v_admin public.admin_users%rowtype;
  v_order_item public.customer_order_items%rowtype;
  v_serialized_unit public.commerce_serialized_units%rowtype;
  v_existing_scan_count integer;
  v_item_has_serialized_units boolean;
  v_item_is_serialized boolean;
begin
  -- Trigger-only boundary: no generic RPC or caller-selected relation/operation.
  if tg_relid <> 'public.order_packing_scans'::regclass
    or tg_op <> 'INSERT'
    or tg_when <> 'BEFORE'
    or tg_level <> 'ROW'
  then
    raise exception 'Invalid packing scan operation.' using errcode = '42501';
  end if;

  -- Recheck the authenticated server actor while holding revocation until commit.
  select admins.* into v_admin
  from public.admin_users as admins
  where admins.id = new.scanned_by
  for share;

  if not found or not coalesce(v_admin.is_active, false)
    or (v_admin.role <> 'owner' and not coalesce(
      v_admin.permissions @> '{"dashboard.view":true,"dashboard.orders":true}'::jsonb,
      false
    ))
  then
    raise exception 'This admin cannot process orders.' using errcode = '42501';
  end if;

  if new.scanned_code is null or length(btrim(new.scanned_code)) not between 1 and 500 then
    raise exception 'Scan or enter a valid item code.';
  end if;

  select sessions.*
  into v_session
  from public.order_packing_sessions as sessions
  where sessions.id = new.session_id
  for update;

  if not found then
    raise exception 'Packing session not found.';
  end if;

  if v_session.status <> 'active' then
    raise exception 'This packing session is no longer active.';
  end if;

  if new.scanned_by is null
    or v_session.admin_user_id is distinct from new.scanned_by
  then
    raise exception 'Only the admin who claimed this order can scan its items.';
  end if;

  -- Session locking serializes scans, release, close and completion. The work
  -- session is read here without another lock: work-session close locks its
  -- parent first, then this same packing-session row.
  if not exists (
    select 1 from public.order_packing_work_sessions as work_sessions
    where work_sessions.id = v_session.work_session_id
      and work_sessions.admin_user_id = new.scanned_by
      and work_sessions.status = 'active'
  ) then
    raise exception 'Your packing session is closed. Start a new session.';
  end if;

  perform 1 from public.customer_orders as orders
  where orders.id = v_session.order_id
    and orders.status in ('pending_payment', 'processing')
    and orders.packing_completed_at is null
  for share;
  if not found then
    raise exception 'This order is not available for packing.';
  end if;

  select order_items.*
  into v_order_item
  from public.customer_order_items as order_items
  where order_items.id = new.order_item_id
    and order_items.order_id = v_session.order_id;

  if not found then
    raise exception 'The scanned item does not belong to this order.';
  end if;

  select exists (
    select 1
    from public.commerce_serialized_units as serialized_units
    where serialized_units.customer_order_item_id = v_order_item.id
      and serialized_units.customer_order_id = v_session.order_id
  )
  into v_item_has_serialized_units;

  select (
    v_order_item.variant_id is not null
    or coalesce(products.is_serialized, false)
    or v_item_has_serialized_units
  )
  into v_item_is_serialized
  from (select 1) as singleton
  left join public.products as products
    on products.id = v_order_item.product_id;

  if new.serialized_unit_id is not null then
    select serialized_units.*
    into v_serialized_unit
    from public.commerce_serialized_units as serialized_units
    where serialized_units.id = new.serialized_unit_id
      and serialized_units.customer_order_id = v_session.order_id
      and serialized_units.customer_order_item_id = v_order_item.id
    for share;

    if not found
      or v_serialized_unit.customer_order_id is distinct from v_session.order_id
      or v_serialized_unit.customer_order_item_id is distinct from v_order_item.id
    then
      raise exception 'This serialized unit is not assigned to the selected order item.';
    end if;

    if v_serialized_unit.status <> 'sold' then
      raise exception 'This serialized unit is not available for packing.';
    end if;

    if lower(btrim(new.scanned_code)) not in (
      lower(v_serialized_unit.id::text),
      lower(v_serialized_unit.qr_token::text),
      lower(btrim(v_serialized_unit.unit_code)),
      lower(btrim(coalesce(v_serialized_unit.serial_number, '')))
    ) then
      raise exception 'The scanned code does not match this serialized unit.';
    end if;

    new.scan_type := 'serialized';
  elsif v_item_is_serialized then
    raise exception 'Scan the exact assigned unit code or QR for this item.';
  else
    if lower(btrim(new.scanned_code)) not in (
      lower(btrim(coalesce(v_order_item.product_sku, ''))),
      lower(btrim(coalesce(v_order_item.variant_sku, ''))),
      lower(btrim(coalesce(v_order_item.variant_code, '')))
    ) then
      raise exception 'The scanned SKU or code does not match this order item.';
    end if;

    new.scan_type := 'sku';
  end if;

  select count(*)::integer
  into v_existing_scan_count
  from public.order_packing_scans as scans
  where scans.session_id = new.session_id
    and scans.order_item_id = new.order_item_id
    and (tg_op = 'INSERT' or scans.id <> new.id);

  if v_existing_scan_count >= v_order_item.quantity then
    raise exception 'The requested quantity for this item is already complete.';
  end if;

  new.scanned_code := btrim(new.scanned_code);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_order_packing_session_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_admin public.admin_users%rowtype;
begin
  if new.admin_user_id is null then
    raise exception 'An active order-processing admin is required.';
  end if;

  select admins.*
  into v_admin
  from public.admin_users as admins
  where admins.id = new.admin_user_id;

  if not found
    or not coalesce(v_admin.is_active, false)
    or (
      v_admin.role <> 'owner'
      and not coalesce(
        (v_admin.permissions ->> 'dashboard.orders')::boolean,
        false
      )
    )
  then
    raise exception 'This admin cannot process orders.';
  end if;

  if new.status <> 'active' then
    raise exception 'A new packing session must start as active.';
  end if;

  new.processor_name := coalesce(
    nullif(btrim(v_admin.full_name), ''),
    nullif(btrim(v_admin.email), ''),
    'Admin'
  );
  new.processor_email := nullif(lower(btrim(v_admin.email)), '');
  new.started_at := coalesce(new.started_at, now());
  new.completed_at := null;
  new.completed_order_status := null;
  new.created_at := coalesce(new.created_at, now());
  new.updated_at := coalesce(new.updated_at, now());
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_order_packing_work_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id
      or new.admin_user_id is distinct from old.admin_user_id
      or new.operator_name is distinct from old.operator_name
      or new.operator_email is distinct from old.operator_email
      or new.started_at is distinct from old.started_at
      or new.created_at is distinct from old.created_at
    then
      raise exception 'Packing work session identity is immutable.';
    end if;

    if old.status = 'closed' then
      raise exception 'A closed packing work session cannot be changed.';
    end if;

    if old.status = 'active' and new.status not in ('active', 'closed') then
      raise exception 'The packing work session status is not valid.';
    end if;

    if new.status = 'closed' and exists (
      select 1
      from public.order_packing_sessions as packing
      where packing.admin_user_id = old.admin_user_id
        and packing.status = 'active'
    ) then
      raise exception 'Release or complete the active order before closing this session.';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.installation_binding(p_binding jsonb)
 RETURNS private.installation_bootstrap
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j private.installation_bootstrap;k text;
begin
 perform private.installation_assert_operator();
 if p_binding is null or jsonb_typeof(p_binding)<>'object' or p_binding-array['installation_id','request_id','target_digest','project_ref','site_origin','owner_email_digest']<>'{}'::jsonb or (select count(*) from jsonb_object_keys(p_binding))<>6 then raise exception 'Invalid installation binding.' using errcode='22023';end if;
 foreach k in array array['installation_id','request_id','target_digest','project_ref','site_origin','owner_email_digest'] loop
  if jsonb_typeof(p_binding->k) is distinct from 'string' then raise exception 'Invalid installation binding.' using errcode='22023';end if;
 end loop;
 if p_binding->>'installation_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or p_binding->>'request_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or p_binding->>'target_digest' !~ '^[0-9a-f]{64}$' or p_binding->>'owner_email_digest' !~ '^[0-9a-f]{64}$' or p_binding->>'project_ref' !~ '^[a-z0-9]{20}$' or public.installation_https_origin(p_binding->>'site_origin') is null then raise exception 'Invalid installation binding.' using errcode='22023';end if;
 select * into strict j from private.installation_bootstrap where singleton for update;
 if j.installation_id::text is distinct from p_binding->>'installation_id' or j.installation_id is distinct from (select installation_id from public.quick_setup_state where singleton) or j.phase='sealed_existing' or (j.binding is not null and j.binding is distinct from p_binding) then raise exception 'Installation binding conflict.' using errcode='42501';end if;
 return j;
end $function$

CREATE OR REPLACE FUNCTION private.installation_journal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 perform private.installation_assert_operator();
 if tg_op in ('DELETE','TRUNCATE') then raise exception 'Installation journal is retained.' using errcode='42501';end if;
 if current_setting('app.installation_write',true) is distinct from 'on' or tg_op<>'UPDATE' then raise exception 'Installation command required.' using errcode='42501';end if;
 if old.phase in ('complete','sealed_existing') or new.singleton is distinct from old.singleton or new.installation_id is distinct from old.installation_id or new.revision<>old.revision+1 or
    (old.binding is not null and (new.binding is distinct from old.binding or new.registered_at is distinct from old.registered_at)) or
    (old.auth_subject is not null and new.auth_subject is distinct from old.auth_subject) or
    not((old.phase='available' and new.phase='registered') or (old.phase='registered' and new.phase='auth_started') or (old.phase='auth_started' and new.phase in ('auth_started','complete'))) then
  raise exception 'Installation checkpoint is immutable.' using errcode='42501';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.installation_link_owner(p_binding jsonb, p_subject uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j private.installation_bootstrap;u auth.users;marker jsonb;permissions_value jsonb;full_name_value text;
begin
 j:=private.installation_binding(p_binding);
 if j.phase='complete' then
  if j.auth_subject is distinct from p_subject then raise exception 'Installation subject conflict.' using errcode='42501';end if;
  return to_jsonb(j); -- Historical receipt, even after demotion/reset/deletion.
 end if;
 if j.phase<>'auth_started' or p_subject is null then raise exception 'Auth request required.' using errcode='42501';end if;
 lock table auth.users,public.admin_users in share row exclusive mode;
 perform private.installation_assert_empty(p_subject);
 select * into u from auth.users where id=p_subject for update;
 marker:=jsonb_build_object('version',1,'installation_id',p_binding->>'installation_id','request_id',p_binding->>'request_id','target_digest',p_binding->>'target_digest','project_ref',p_binding->>'project_ref');
 if u.id is null or u.is_anonymous or u.email_confirmed_at is null or u.created_at is null or u.created_at<j.registered_at or u.raw_app_meta_data->'elcomputer_bootstrap' is distinct from marker or
    encode(sha256(convert_to(lower(btrim(u.email)),'UTF8')),'hex') is distinct from p_binding->>'owner_email_digest' then raise exception 'Unverifiable installation identity.' using errcode='42501';end if;
 select jsonb_object_agg(key,true) into permissions_value from jsonb_object_keys(public.default_admin_permissions()) key;
 full_name_value:=left(coalesce(u.raw_user_meta_data->>'full_name',''),120);
 insert into public.admin_users(id,email,full_name,role,permissions,is_active) values(u.id,lower(btrim(u.email)),full_name_value,'owner',permissions_value,true);
 insert into public.admin_activity_logs(admin_user_id,author_name,author_email,author_role,action_key,description,metadata)
  values(u.id,coalesce(nullif(full_name_value,''),lower(btrim(u.email))),lower(btrim(u.email)),'owner','installation.owner.bootstrap','Created the first installation owner.',jsonb_build_object('installation_id',j.installation_id,'request_id',p_binding->>'request_id','auth_subject',u.id));
 perform set_config('app.installation_write','on',true);
 update private.installation_bootstrap set phase='complete',revision=revision+1,auth_subject=u.id,completed_at=clock_timestamp(),error_code=null where singleton returning * into j;
 perform set_config('app.installation_write','',true);
 return to_jsonb(j);
end $function$

CREATE OR REPLACE FUNCTION private.installation_record_error(p_binding jsonb, p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j private.installation_bootstrap;
begin
 j:=private.installation_binding(p_binding);
 if j.phase='complete' then return;end if;
 if j.phase<>'auth_started' or p_code is null or p_code not in ('auth_unresolved','identity_conflict','promotion_failed') then raise exception 'Invalid installation error.' using errcode='22023';end if;
 perform set_config('app.installation_write','on',true);
 update private.installation_bootstrap set revision=revision+1,error_code=p_code where singleton;
 perform set_config('app.installation_write','',true);
end $function$

CREATE OR REPLACE FUNCTION private.installation_register(p_binding jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j private.installation_bootstrap;
begin
 j:=private.installation_binding(p_binding);
 if j.phase='available' then
  lock table auth.users,public.admin_users in share row exclusive mode;
  perform private.installation_assert_empty();
  perform set_config('app.installation_write','on',true);
  update private.installation_bootstrap set binding=p_binding,phase='registered',revision=revision+1,registered_at=clock_timestamp() where singleton returning * into j;
