CREATE OR REPLACE FUNCTION catalog_private.media_canonical(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare part text; parts text[]:=array[]::text[];
begin
  foreach part in array string_to_array(substr(value,10),'/') loop
    if part='' or part='.' then continue; end if;
    if part='..' then
      if cardinality(parts)=0 then return null; end if;
      parts:=parts[1:cardinality(parts)-1];
    else parts:=array_append(parts,part); end if;
  end loop;
  return '/uploads/'||array_to_string(parts,'/');
end $function$

CREATE OR REPLACE FUNCTION catalog_private.media_decode(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare item text; n integer; result text:=value;
begin
  for item in select distinct m[1] from regexp_matches(value,'%([0-9a-fA-F]{2})','g') m loop
    n:=get_byte(decode(item,'hex'),0);
    if n between 32 and 126 then result:=replace(result,'%'||item,chr(n)); end if;
  end loop;
  return result;
end $function$

CREATE OR REPLACE FUNCTION catalog_private.product_list_stock(p public.products)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q integer;
begin
  if p.is_serialized then
    if public.get_active_erp_mode()='daftra' then
      select coalesce(sum(public.erp_storefront_stock('product_variant',v.id,0)),0)::integer into q
        from public.product_variants v where v.product_id=p.id and v.is_active;
    else
      select count(*)::integer into q from public.commerce_serialized_units u
        join public.product_variants v on v.id=u.variant_id and v.product_id=p.id and v.is_active
        where u.product_id=p.id and u.warehouse_id=p.primary_warehouse_id and u.status='in_stock';
    end if;
  else
    q:=public.erp_storefront_stock('product',p.id,p.stock_quantity);
  end if;
  return greatest(coalesce(q,0),0);
end $function$

