CREATE OR REPLACE FUNCTION catalog_private.reset_clear_media(p_owner uuid, p_files jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare paths text[]:=catalog_private.reset_media_paths(p_files); col record; path text; plan jsonb; affected uuid[];
begin
 plan:=public.system_reset_media_plan(p_owner,p_files);
 if jsonb_array_length(plan->'blockers')>0 then
  raise exception 'Images remain in authored content. Remove those references first.';
 end if;
 select array_agg(distinct id) into affected from (
  select p.id from public.products p,lateral catalog_private.media_references(to_jsonb(p)) x where x=any(paths)
  union select v.product_id from public.product_variants v,lateral catalog_private.media_references(to_jsonb(v)) x where x=any(paths)
  union select i.product_id from public.product_images i,lateral catalog_private.media_references(to_jsonb(i)) x where x=any(paths)
 ) products;
 for col in select table_name,column_name from information_schema.columns where table_schema='public'
  and table_name=any(catalog_private.reset_media_tables()) and column_name=any(catalog_private.reset_media_columns())
  and data_type in ('text','character varying') order by table_name,column_name loop
  -- Reference and editorial triggers remain enabled for these updates.
  execute format('update public.%I set %I=%L where case when %I like %L then lower(catalog_private.media_canonical(catalog_private.media_decode(split_part(split_part(%I,''?'',1),''#'',1)))) end=any($1)',
   col.table_name,col.column_name,'',col.column_name,'/uploads/%',col.column_name) using paths;
 end loop;
 -- Galleries/SEO can change independently of the main revision trigger.
 -- Conservative advancement also protects loaded variants/section snapshots.
 update catalog_private.product_revisions r set revision=r.revision+1 where r.product_id=any(affected);
 foreach path in array paths loop perform public.catalog_media_delete(p_owner,path,false);end loop;
end $function$

CREATE OR REPLACE FUNCTION catalog_private.reset_manifest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare paths jsonb; bucket text; kind text; n integer;
begin
 if new.manifest->>'format' is distinct from '2' then return new;end if;
 if new.scope in ('commerce','full') then
  update private.salary_payment_commands set retired_by_reset=true where not retired_by_reset;
 end if;
 if new.scope='media' then perform catalog_private.reset_clear_media(new.owner_id,new.manifest->'media');end if;
 if new.scope in ('products','full') then
  update catalog_private.import_jobs j set closed_reason='reset'
   where j.closed_reason is null and exists(select 1 from catalog_private.import_items i where i.job_id=j.id and i.status='pending');
  update catalog_private.import_items i set status='failed',reason='reset',finished_at=clock_timestamp()
   where i.status='pending' and exists(select 1 from catalog_private.import_jobs j where j.id=i.job_id and j.closed_reason='reset');
 end if;
 if new.scope in ('orders','commerce','full') then
  if exists(select 1 from public.order_packing_videos where status='uploading')
   or exists(select 1 from public.shipping_order_jobs where state in ('submitting','label_pending')) then
   raise exception 'Finish pending packing or shipping work before resetting.';
  end if;
 end if;
 -- Capture before the corresponding business rows are deleted. Never write to
 -- managed Storage tables. Full owns these six application buckets only.
 foreach kind in array array['documents','support','chat','packing','labels','evidence'] loop
  paths:='[]';bucket:=case kind when 'documents' then 'admin-documents' when 'support' then 'support-attachments'
   when 'chat' then 'chat-attachments' when 'packing' then 'order-packing-videos' when 'labels' then 'shipping-labels' else 'after-sales-evidence' end;
  if new.scope='full' then
   select coalesce(jsonb_agg(name order by name),'[]') into paths from (
    select o.name from storage.objects o where o.bucket_id=bucket
     and not(kind='evidence' and exists(select 1 from public.after_sales_claim_evidence e where e.storage_path=o.name))
     and not(kind='labels' and exists(select 1 from public.shipping_claim_jobs j where j.label_storage_path=o.name))
     order by o.name limit 10001) objects;
  elsif new.scope='documents' and kind='documents' then
   select coalesce(jsonb_agg(name order by name),'[]') into paths from (
    select name from storage.objects where bucket_id=bucket order by name limit 10001) objects;
  elsif new.scope in ('orders','commerce') and kind='packing' then
   select coalesce(jsonb_agg(storage_path order by storage_path),'[]') into paths from (
    select distinct storage_path from public.order_packing_videos order by storage_path limit 10001) objects;
  elsif new.scope in ('orders','commerce') and kind='labels' then
   select coalesce(jsonb_agg(label_storage_path order by label_storage_path),'[]') into paths from (
    select distinct label_storage_path from public.shipping_order_jobs where label_storage_path is not null
     and not exists(select 1 from public.shipping_claim_jobs j where j.label_storage_path=shipping_order_jobs.label_storage_path)
     order by label_storage_path limit 10001) objects;
  end if;
  new.manifest:=jsonb_set(new.manifest,array[kind],paths);
 end loop;
 select sum(jsonb_array_length(value)) into n from jsonb_each(new.manifest) where jsonb_typeof(value)='array';
 if n>10000 then raise exception 'Too many cleanup items. Reset a smaller scope first.';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION catalog_private.reset_media_paths(p_files jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare f jsonb; paths text[]:=array[]::text[]; path text;
begin
 if jsonb_typeof(p_files) is distinct from 'array' or jsonb_array_length(p_files)>10000
  or octet_length(p_files::text)>8388608 then raise exception 'Invalid reset upload manifest.' using errcode='22023';end if;
 for f in select value from jsonb_array_elements(p_files) loop
  path:=f->>'path';
  if jsonb_typeof(f) is distinct from 'object' or path is null or length(path)>500
   or path !~* '^((products/(gallery/)?|categories/|brands/|pages/|settings/(site-logo|auth-page|hero-banners|banner-ads|footer|offer-cards)/)?[A-Za-z0-9_][A-Za-z0-9_.-]*\.(jpg|jpeg|png|gif|webp|avif|svg))$'
   or jsonb_typeof(f->'root') is distinct from 'string' or f->>'root' not like '/%'
   or jsonb_typeof(f->'size') is distinct from 'number' or (f->>'size')::numeric<0
   or jsonb_typeof(f->'modifiedAt') is distinct from 'number' then
   raise exception 'Invalid reset upload manifest.' using errcode='22023';
  end if;
  paths:=array_append(paths,lower('/uploads/'||path));
 end loop;
 -- Case aliases share the existing conservative media reservation.
 return array(select distinct x from unnest(paths) x order by x);
end $function$

CREATE OR REPLACE FUNCTION catalog_private.reset_media_projection(p_document jsonb, p_paths text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare key text; value text;
begin
 foreach key in array catalog_private.reset_media_columns() loop
  value:=p_document->>key;
  if value like '/uploads/%' then
   if lower(catalog_private.media_canonical(catalog_private.media_decode(split_part(split_part(value,'?',1),'#',1))))=any(p_paths) then
    p_document:=jsonb_set(p_document,array[key],'""'::jsonb);
   end if;
  end if;
 end loop;
 return p_document;
end $function$

CREATE OR REPLACE FUNCTION catalog_private.reset_storage_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare path text:=to_jsonb(new)->>tg_argv[1];
begin
 if path is null or (tg_op='UPDATE' and path is not distinct from to_jsonb(old)->>tg_argv[1]) then return new;end if;
 if exists(select 1 from public.system_reset_runs r where r.status='cleanup_pending'
  and coalesce(r.manifest->tg_argv[0],'[]') ? path) then
  raise exception 'This file is reserved by a pending reset.' using errcode='40001';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION catalog_private.system_reset_begin_legacy(p_owner uuid, p_scope text, p_id uuid, p_media_files jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '10s'
 SET statement_timeout TO '120s'
AS $function$
declare
  v_tables text[] := public.system_reset_tables(p_scope);
  v_remaining text[];
  v_table text;
  v_trigger record;
  v_triggers jsonb := '[]';
  v_restore jsonb;
  v_plan jsonb;
  v_actor jsonb;
  v_run public.system_reset_runs%rowtype;
  v_manifest jsonb := jsonb_build_object('format',2,'media',p_media_files,'documents','[]'::jsonb,'users','[]'::jsonb);
  v_column record;
begin
  if p_scope in ('products','commerce','content','full') then perform public.assert_built_in_erp(); end if;
  perform public.system_reset_assert_owner(p_owner);
  if not pg_try_advisory_xact_lock(hashtextextended('elcomputer-system-reset', 0)) then
    raise exception 'Another reset is running.';
  end if;
  select * into v_run from public.system_reset_runs where id = p_id for update;
  if found then
    if v_run.owner_id <> p_owner or v_run.scope <> p_scope then raise exception 'Reset request does not match.'; end if;
    return to_jsonb(v_run);
  end if;
  if exists (select 1 from public.system_reset_runs where status = 'cleanup_pending') then
    raise exception 'Finish the pending reset before starting another.';
  end if;
  -- Exclusive locks prevent concurrent changes between the dependency check and deletion.
  for v_table in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r'
      and c.relname <> all(array['system_reset_runs', 'system_reset_attempts']) order by c.relname
  loop
    execute format('lock table public.%I in access exclusive mode', v_table);
  end loop;

  if p_scope='full' and exists(select 1 from public.sms_batches where status='processing') then
    raise exception 'Wait for the SMS worker to finish before resetting.';
  end if;
  v_plan := public.system_reset_plan(p_owner, p_scope);
  if jsonb_array_length(v_plan->'blockers') > 0 then
    raise exception 'Linked records prevent this reset. Review the affected data first.';
  end if;
  select jsonb_build_object('name', coalesce(nullif(full_name, ''), email), 'email', email) into v_actor
    from public.admin_users where id = p_owner;
  if p_scope in ('documents', 'full') and to_regclass('storage.objects') is not null then
    select jsonb_set(v_manifest, '{documents}', coalesce(jsonb_agg(name), '[]')) into v_manifest
      from (select name from storage.objects where bucket_id='admin-documents' order by name limit 10001) objects;
  end if;
  if p_scope = 'full' then
    select jsonb_set(v_manifest, '{users}', coalesce(jsonb_agg(id), '[]')) into v_manifest from (select id from auth.users where id<>p_owner order by id limit 10001) users;
  end if;
  insert into public.system_reset_runs (id, owner_id, scope, status, actor, summary, manifest)
    values (p_id, p_owner, p_scope, 'cleanup_pending', v_actor, v_plan->'counts', v_manifest);
  -- Flush deferred constraint events before changing trigger state. Keep FK checks immediate.
  set constraints all immediate;
  -- Only application triggers are suspended, inside this transaction. FK constraints stay active.
  -- Their original enabled/replica/always states are restored before commit, or rolled back on error.
  for v_trigger in
    select t.tgname, t.tgenabled, c.relname from pg_trigger t join pg_class c on c.oid = t.tgrelid
      join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and not t.tgisinternal and t.tgenabled <> 'D'
      and c.relname = any(v_tables || case when p_scope = 'media' then array['products', 'product_variants', 'product_images', 'categories', 'brands', 'site_settings', 'site_hero_banners', 'site_offer_cards', 'customer_order_items'] else array[]::text[] end)
  loop
    v_triggers := v_triggers || jsonb_build_array(to_jsonb(v_trigger));
    execute format('alter table public.%I disable trigger %I', v_trigger.relname, v_trigger.tgname);
  end loop;
  if 'customer_orders' = any(v_tables) and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'customer_orders' and column_name = 'awaiting_customer_message_id') then
    update public.customer_orders set awaiting_customer_message_id = null;
  end if;
  if p_scope in ('orders', 'commerce') and to_regclass('public.erp_sync_jobs') is not null then
    execute 'delete from public.erp_sync_jobs where local_entity_type = $1' using 'customer_order';
  end if;
  if p_scope in ('orders', 'commerce') and to_regclass('public.erp_entity_links') is not null then
    execute 'delete from public.erp_entity_links where local_entity_type = $1' using 'customer_order';
  end if;
  if p_scope = 'products' and to_regclass('public.erp_entity_links') is not null then
    execute 'delete from public.erp_entity_links where local_entity_type = any($1)' using array['product', 'product_variant']::text[];
  end if;
  select array_agg(t) into v_remaining from unnest(v_tables) t where to_regclass(format('public.%I', t)) is not null;
  while cardinality(v_remaining) > 0 loop
    select candidate into v_table from unnest(v_remaining) candidate
    where not exists (
      select 1 from pg_constraint fk join pg_class child on child.oid = fk.conrelid
      where fk.contype = 'f' and fk.confrelid = to_regclass(format('public.%I', candidate))
        and child.relname = any(v_remaining) and fk.conrelid <> fk.confrelid
        and fk.conname <> 'customer_orders_awaiting_customer_message_fkey'
    ) limit 1;
    if v_table is null then raise exception 'Unresolved reset dependency. No data was erased.'; end if;
    execute format('delete from public.%I', v_table);
    v_remaining := array_remove(v_remaining, v_table);
  end loop;
  if p_scope = 'commerce' then
    perform set_config('app.serialized_inventory_write', 'on', true);
    update public.products set stock_quantity = 0, cost_price = 0;
    if to_regclass('public.product_variants') is not null then
      update public.product_variants set stock_quantity = 0, cost_price = 0;
    end if;
  end if;
  if false then
    for v_column in select table_name, column_name from information_schema.columns
      where table_schema = 'public' and data_type in ('text', 'character varying')
        and table_name = any(array['products', 'product_variants', 'product_images', 'categories', 'brands', 'site_settings', 'site_hero_banners', 'site_offer_cards', 'customer_order_items'])
        and column_name = any(array['image_url', 'logo_url', 'site_logo_url', 'banner_ad_1_image_url', 'banner_ad_2_image_url'])
    loop
      execute format('update public.%I set %I = %L where %I like %L', v_column.table_name, v_column.column_name, '', v_column.column_name, '/uploads/%');
    end loop;
  end if;

  if p_scope = 'full' then
    insert into public.chat_settings(singleton,is_enabled,attachments_enabled,auto_assignment_enabled,sound_notifications_enabled,request_call_enabled)
      values(true,false,false,false,false,false);
    insert into public.shipping_provider_settings(id,display_name,base_url,company_id,product_id)
      values('pdc','PDC Courier','https://clientsapi.pdc-eg.com/api/ClientUsers/V6/',null,null);
    delete from public.admin_users where id <> p_owner;
    update public.system_reset_runs set actor='{}',summary='{}',manifest='{}',cleanup_progress='{}' where id<>p_id and status='completed';
    delete from public.system_reset_attempts where owner_id <> p_owner;
    if to_regclass('public.store_analytics_internal_users') is not null then
      insert into public.store_analytics_internal_users(user_id) values (p_owner) on conflict do nothing;
    end if;
    if to_regclass('public.commerce_serialized_unit_code_seq') is not null then
      alter sequence public.commerce_serialized_unit_code_seq restart with 1;
    end if;
  end if;
  for v_restore in select value from jsonb_array_elements(v_triggers) loop
    execute format('alter table public.%I enable %s trigger %I', v_restore->>'relname',
      case v_restore->>'tgenabled' when 'A' then 'always' when 'R' then 'replica' else '' end, v_restore->>'tgname');
  end loop;
  select * into v_run from public.system_reset_runs where id = p_id;
  return to_jsonb(v_run);
end;
$function$

CREATE OR REPLACE FUNCTION catalog_private.system_reset_finish_legacy(p_owner uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_run public.system_reset_runs%rowtype;
begin
  perform public.system_reset_assert_owner(p_owner);
  select * into v_run from public.system_reset_runs where id = p_id and owner_id = p_owner for update;
  if not found then raise exception 'Reset request not found.'; end if;
  if v_run.status <> 'completed' then
    -- This is intentionally inserted AFTER all database, file and account cleanup.
    insert into public.admin_activity_logs (admin_user_id, author_name, author_email, author_role, action_key, description, metadata, created_at)
      values (p_owner, v_run.actor->>'name', v_run.actor->>'email', 'owner', 'settings.system_reset.completed',
        format('%s completed the %s reset.', v_run.actor->>'name', v_run.scope),
        jsonb_build_object('reset_id', p_id, 'scope', v_run.scope, 'records', v_run.summary), clock_timestamp());
    update public.system_reset_runs set status = 'completed', completed_at = clock_timestamp(), manifest = '{}' where id = p_id returning * into v_run;
  end if;
  return jsonb_build_object('id', v_run.id, 'scope', v_run.scope, 'status', v_run.status, 'completed_at', v_run.completed_at);
end;
$function$

CREATE OR REPLACE FUNCTION catalog_private.system_reset_plan_legacy(p_owner uuid, p_scope text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tables text[] := public.system_reset_tables(p_scope);
  v_table text;
  v_count bigint;
  v_counts jsonb := '{}';
  v_blockers jsonb := '[]';
  v_fk record;
  v_predicate text;
  v_unknown text[];
begin
  perform public.system_reset_assert_owner(p_owner);
  if p_scope = 'full' then
    select array_agg(c.relname) into v_unknown
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p')
      and not c.relname = any(v_tables || array['admin_users', 'system_reset_runs', 'system_reset_attempts', 'after_sales_policies', 'after_sales_return_reasons', 'after_sales_policy_versions', 'after_sales_claims', 'after_sales_claim_events', 'after_sales_claim_information', 'after_sales_claim_evidence', 'shipping_claim_jobs', 'email_provider_settings', 'email_templates', 'email_preferences', 'email_messages', 'email_attempts', 'email_events', 'after_sales_communication_settings', 'after_sales_communications', 'quick_setup_state', 'quick_setup_revisions', 'quick_setup_events']);
    if cardinality(v_unknown) > 0 then
      raise exception 'Unrecognized tables found. Update the reset scope before continuing.' using errcode = 'P0001';
    end if;
  end if;
  foreach v_table in array v_tables loop
    if to_regclass(format('public.%I', v_table)) is not null then
      execute format('select count(*) from public.%I', v_table) into v_count;
      v_counts := v_counts || jsonb_build_object(v_table, v_count);
    end if;
  end loop;
  -- Never silently cascade into data outside the selected scope.
  for v_fk in
    select con.*, src.relname as source_name, ns.nspname as source_schema
    from pg_constraint con
    join pg_class target on target.oid = con.confrelid
    join pg_namespace tn on tn.oid = target.relnamespace
    join pg_class src on src.oid = con.conrelid
    join pg_namespace ns on ns.oid = src.relnamespace
    where con.contype = 'f' and tn.nspname = 'public' and target.relname = any(v_tables)
      and not (ns.nspname = 'public' and src.relname = any(v_tables))
      and not (ns.nspname='public' and src.relname='after_sales_policies' and target.relname in ('products','categories') and con.confdeltype='c') and con.confdeltype <> 'n'
  loop
    select string_agg(format('%I is not null', a.attname), ' and ') into v_predicate
    from pg_attribute a where a.attrelid = v_fk.conrelid and a.attnum = any(v_fk.conkey);
    execute format('select count(*) from %I.%I where %s', v_fk.source_schema, v_fk.source_name, v_predicate) into v_count;
    if v_count > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('table', v_fk.source_name, 'count', v_count));
    end if;
  end loop;
  if p_scope = 'full' then
    select count(*) into v_count from auth.users where id <> p_owner;
    v_counts := v_counts || jsonb_build_object('other_user_accounts', v_count);
  end if;

  if p_scope='full' then
   select (select count(*) from public.email_messages)+(select count(*) from public.email_preferences)+(select count(*) from public.email_templates)+(select count(*) from public.email_provider_settings where api_key_encrypted is not null or webhook_token_encrypted is not null or updated_by is not null) into v_count;
   if v_count>0 then v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('table','email_retained_data','count',v_count)); end if;
  end if;

  if p_scope='full' then
   select (select count(*) from public.after_sales_communications)+(select count(*) from public.after_sales_communication_settings where updated_by is not null) into v_count;
   if v_count>0 then v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('table','claim_communications_retained','count',v_count));end if;
  end if;
  return jsonb_build_object('counts', v_counts, 'blockers', v_blockers);


end;
$function$

CREATE OR REPLACE FUNCTION catalog_private.track_variant_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ids uuid[]; tracked_id uuid;
begin
  if tg_op='UPDATE' and
    (to_jsonb(old)-array['stock_quantity','cost_price','price','updated_at','created_at'])
      is not distinct from
    (to_jsonb(new)-array['stock_quantity','cost_price','price','updated_at','created_at']) then
    return null;
  end if;
  ids:=case when tg_op='INSERT' then array[new.product_id]
    when tg_op='DELETE' then array[old.product_id] else array[old.product_id,new.product_id] end;
  for tracked_id in select distinct x from unnest(ids) x order by x loop
    -- Deletion retains minimal generation/receipt tombstones without catalog values.
    if exists(select 1 from public.products p where p.id=tracked_id) then
      insert into catalog_private.product_revisions(product_id,revision) values(tracked_id,1)
        on conflict(product_id) do update set revision=catalog_private.product_revisions.revision+1;
    end if;
  end loop;
  return null;
end $function$
